// PV6 share links, over the real router, index core, policy engine and SQLite D1. Guests reach the internal routes
// exactly as serve-worker does (no actor). Fixtures are generated bytes, never real files.

import { randomBytes } from "node:crypto";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});
afterAll(() => {
  delete (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream;
});

describe("share links", () => {
  let w: World;
  let A: { id: string; pub: string };
  let owner: User, editor: User, viewer: User, guest: User;
  let base: string;
  let baseB: string;

  beforeEach(async () => {
    w = new World();
    w.now = new Date(); // tickets and expiry use the request clock
    A = w.newOrg();
    owner = w.newUser("owner");
    editor = w.newUser("editor");
    viewer = w.newUser("viewer");
    guest = w.newUser("guest");
    w.grant(A, owner, "owner");
    w.grant(A, editor, "builder");
    w.grant(A, viewer, "viewer");
    const lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Shared" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    const libB = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Other" })).json.data.library;
    baseB = `/v1/organizations/${A.pub}/libraries/${libB.id}`;
    await w.call(owner, "PUT", `${base}/members/${editor.id}`, { role: "editor" });
    await w.call(owner, "PUT", `${base}/members/${viewer.id}`, { role: "viewer" });
    await w.call(owner, "POST", `${base}/invitations`, { email: guest.email, role: "uploader" });
    await w.call(guest, "POST", "/v1/media/invitations/accept");
  });

  async function upload(lib: string, name: string, folder = "/", bytes: Uint8Array = randomBytes(300), mime = "application/octet-stream") {
    const s = (await w.call(owner, "POST", `${lib}/uploads`, { name, folder, size: bytes.length, sha256: sha256hex(bytes), mime })).json.data.session;
    await w.put(owner, `${lib}/uploads/${s.id}/parts/1`, bytes);
    const f = (await w.call(owner, "POST", `${lib}/uploads/${s.id}/commit`)).json.data.file;
    await w.runPipelines();
    return { ...f, bytes };
  }

  const token = (url: string) => url.split("/_s/")[1]!;
  const open = (t: string, extra: Record<string, unknown> = {}) => w.call(null, "POST", "/v1/media/shares/open", { token: t, ...extra });
  const content = async (t: string, fileId: string, extra: Record<string, unknown> = {}) => {
    const res = await w.raw("POST", "/v1/media/shares/content", { token: t, fileId, ...extra });
    return { status: res.status, headers: res.headers, bytes: new Uint8Array(await res.arrayBuffer()) };
  };
  const share = async (body: Record<string, unknown>, user = editor) => w.call(user, "POST", `${base}/share-links`, body);

  it("a file link opens that file only; its bytes stream; the token is stored only as a hash", async () => {
    const f = await upload(base, "report.pdf", "/docs", randomBytes(500), "application/pdf");
    const other = await upload(base, "other.bin", "/docs");
    const r = await share({ target: { kind: "file", fileId: f.id } });
    expect(r.status).toBe(201);
    expect(r.json.data.url).toMatch(/^https:\/\/serve\.test\/_s\/[A-Za-z0-9_-]{43}$/);
    expect(r.json.data.shareLink).toMatchObject({ targetKind: "file", target: f.id, targetLabel: "report.pdf", mode: "view", hasPassword: false, status: "active" });
    const t = token(r.json.data.url);
    const rows = w.db.prepare(`SELECT * FROM media_share_links`).all() as Record<string, unknown>[];
    expect(JSON.stringify(rows)).not.toContain(t);

    const o = await open(t);
    expect(o.status).toBe(200);
    expect(o.json.data.files.map((x: { id: string }) => x.id)).toEqual([f.id]);
    expect(o.json.data.share).toMatchObject({ kind: "file", mode: "view", label: "report.pdf" });
    const c = await content(t, f.id);
    expect(c.status).toBe(200);
    expect(Buffer.from(c.bytes).equals(Buffer.from(f.bytes))).toBe(true);
    expect(c.headers.get("content-disposition")).toMatch(/^inline;/); // PDF is in the inline list, view mode
    expect(c.headers.get("cache-control")).toBe("private, no-store");
    expect(c.headers.get("content-security-policy")).toContain("sandbox");
    expect(c.headers.get("referrer-policy")).toBe("no-referrer");

    // every other file is 404 through this link, in this library and in another
    expect((await content(t, other.id)).status).toBe(404);
    const elsewhere = await upload(baseB, "b.bin");
    expect((await content(t, elsewhere.id)).status).toBe(404);
    expect((await content(t, "fil_" + "0".repeat(32))).status).toBe(404);
    // the open trail counts opens
    const listed = (await w.call(editor, "GET", `${base}/share-links?file=${f.id}`)).json.data.shareLinks;
    expect(listed).toHaveLength(1);
    expect(listed[0].opens).toBe(1);
  });

  it("a folder link shows served files under it, not its siblings, nor files still processing or held", async () => {
    await upload(base, "a.bin", "/trip");
    await upload(base, "b.bin", "/trip/day1");
    const sibling = await upload(base, "c.bin", "/tripod");
    await upload(base, "d.bin", "/");
    // an image waits for the pipeline: not served yet, so not shared
    const s = (await w.call(owner, "POST", `${base}/uploads`, { name: "wait.jpg", folder: "/trip", size: 4, sha256: sha256hex(new Uint8Array([1, 2, 3, 4])), mime: "image/jpeg" })).json.data.session;
    await w.put(owner, `${base}/uploads/${s.id}/parts/1`, new Uint8Array([1, 2, 3, 4]));
    await w.call(owner, "POST", `${base}/uploads/${s.id}/commit`);

    const r = await share({ target: { kind: "folder", path: "/trip" } });
    expect(r.status).toBe(201);
    const t = token(r.json.data.url);
    const o = await open(t);
    expect(o.json.data.files.map((x: { name: string; folder: string }) => `${x.folder}|${x.name}`).sort()).toEqual(["/day1|b.bin", "/|a.bin"]);
    expect(o.json.data.share.label).toBe("trip");
    expect((await content(t, sibling.id)).status).toBe(404);
    expect((await share({ target: { kind: "folder", path: "/nowhere" } })).status).toBe(404);
  });

  it("revoking a link makes the next request 404, landing and bytes alike", async () => {
    const f = await upload(base, "x.bin");
    const r = await share({ target: { kind: "file", fileId: f.id } });
    const t = token(r.json.data.url);
    expect((await content(t, f.id)).status).toBe(200);
    const del = await w.call(editor, "DELETE", `${base}/share-links/${r.json.data.shareLink.id}`);
    expect(del.json.data.shareLink.status).toBe("revoked");
    expect((await open(t)).status).toBe(404);
    expect((await content(t, f.id)).status).toBe(404);
  });

  it("expiry, download limits and modes", async () => {
    const f = await upload(base, "song.bin");
    const exp = await share({ target: { kind: "file", fileId: f.id }, expiresIn: 3600 });
    const te = token(exp.json.data.url);
    expect((await open(te)).status).toBe(200);
    w.now = new Date(w.now.getTime() + 3601_000);
    expect((await open(te)).status).toBe(410);
    expect((await content(te, f.id)).status).toBe(410);
    w.now = new Date();

    const lim = await share({ target: { kind: "file", fileId: f.id }, mode: "download", maxDownloads: 2 });
    const tl = token(lim.json.data.url);
    const d1 = await content(tl, f.id);
    expect(d1.status).toBe(200);
    expect(d1.headers.get("content-disposition")).toMatch(/^attachment;/);
    expect((await content(tl, f.id)).status).toBe(200);
    expect((await content(tl, f.id)).status).toBe(410);
    expect((await open(tl)).status).toBe(410);
    const listed = (await w.call(editor, "GET", `${base}/share-links`)).json.data.shareLinks.find((x: { id: string }) => x.id === lim.json.data.shareLink.id);
    expect(listed).toMatchObject({ downloads: 2, status: "used_up" });

    // view mode: inline viewing of a safe type doesn't count; an explicit download does
    const img = await upload(base, "pic.png", "/", randomBytes(100), "image/png");
    const v = await share({ target: { kind: "file", fileId: img.id }, maxDownloads: 1 });
    const tv = token(v.json.data.url);
    for (let i = 0; i < 3; i++) expect((await content(tv, img.id)).status).toBe(200);
    expect((await content(tv, img.id, { download: true })).status).toBe(200);
    expect((await content(tv, img.id, { download: true })).status).toBe(410);
  });

  it("a password link needs the password, and a proof unlocks only that link", async () => {
    const f = await upload(base, "secret.bin");
    const g = await upload(base, "secret2.bin");
    const r = await share({ target: { kind: "file", fileId: f.id }, password: "correct horse" });
    expect(r.json.data.shareLink.hasPassword).toBe(true);
    const t = token(r.json.data.url);
    const locked = await open(t);
    expect(locked.status).toBe(401);
    expect(locked.json.error.details.wrong).toBe(false);
    expect((await content(t, f.id)).status).toBe(401);
    const wrong = await open(t, { password: "nope nope" });
    expect(wrong.status).toBe(401);
    expect(wrong.json.error.details.wrong).toBe(true);
    const right = await open(t, { password: "correct horse" });
    expect(right.status).toBe(200);
    const proof = right.json.data.proof.value as string;
    expect(proof).toMatch(/^\d+\.[A-Za-z0-9_-]+$/);
    expect((await open(t, { proof })).status).toBe(200);
    expect((await content(t, f.id, { proof })).status).toBe(200);
    expect((await content(t, f.id, { proof: proof.replace(/.$/, (c) => (c === "A" ? "B" : "A")) })).status).toBe(401);
    // the same proof means nothing on another password link
    const r2 = await share({ target: { kind: "file", fileId: g.id }, password: "correct horse" });
    expect((await open(token(r2.json.data.url), { proof })).status).toBe(401);
    // the stored hash is PBKDF2, never the password
    const stored = (w.db.prepare(`SELECT password_hash FROM media_share_links WHERE password_hash IS NOT NULL LIMIT 1`).get() as { password_hash: string }).password_hash;
    expect(stored).toMatch(/^pbkdf2-sha256\$100000\$/);
    expect(stored).not.toContain("correct horse");
  });

  it("only editors and managers share; nothing unserved can be shared; inputs are bounded; sharing off refuses", async () => {
    const f = await upload(base, "y.bin");
    expect((await share({ target: { kind: "file", fileId: f.id } }, viewer)).status).toBe(404);
    expect((await share({ target: { kind: "file", fileId: f.id } }, guest)).status).toBe(404);
    expect((await w.call(viewer, "GET", `${base}/share-links`)).status).toBe(404);
    for (const bad of [
      { target: { kind: "file" } },
      { target: { kind: "folder", path: "/" } },
      { target: { kind: "file", fileId: f.id }, mode: "edit" },
      { target: { kind: "file", fileId: f.id }, expiresIn: 10 },
      { target: { kind: "file", fileId: f.id }, password: "short" },
      { target: { kind: "file", fileId: f.id }, maxDownloads: 0 },
    ]) expect([JSON.stringify(bad), (await share(bad)).status]).toEqual([JSON.stringify(bad), 422]);
    const core = [...w.index.cores.values()][0]!;
    core.takedown(f.id.slice(4).replace(/(.{8})(.{4})(.{4})(.{4})(.{12})/, "$1-$2-$3-$4-$5"), "t", new Date().toISOString());
    expect((await share({ target: { kind: "file", fileId: f.id } })).status).toBe(409);
    w.env.PUBLIC_SHARING = "off";
    const g = await upload(base, "z.bin");
    expect((await share({ target: { kind: "file", fileId: g.id } })).status).toBe(409);
  });

  it("a link to a file taken down later answers 451; a suspended team's links answer 451; sharing off answers 404", async () => {
    const f = await upload(base, "later.bin");
    const t = token((await share({ target: { kind: "file", fileId: f.id } })).json.data.url);
    const core = [...w.index.cores.values()][0]!;
    core.takedown(f.id.slice(4).replace(/(.{8})(.{4})(.{4})(.{4})(.{12})/, "$1-$2-$3-$4-$5"), "t", new Date().toISOString());
    expect((await open(t)).status).toBe(451);
    expect((await content(t, f.id)).status).toBe(451);

    const g = await upload(base, "fine.bin");
    const t2 = token((await share({ target: { kind: "file", fileId: g.id } })).json.data.url);
    w.db.prepare(`INSERT INTO media_org_status (org_id, suspended_at, reason, decided_by) VALUES (?, ?, 'test', 'op')`).run(A.id, new Date().toISOString());
    expect((await open(t2)).status).toBe(451);
    w.db.prepare(`DELETE FROM media_org_status`).run();
    expect((await open(t2)).status).toBe(200);
    w.env.PUBLIC_SHARING = "off";
    expect((await open(t2)).status).toBe(404);
    expect((await open("not-a-token")).status).toBe(404);
  });
});
